CREATE PROCEDURE ocserv_switch_desired_groups() SQL SECURITY DEFINER
BEGIN
 DECLARE finished BOOLEAN DEFAULT FALSE;
 DECLARE constraint_name_value VARCHAR(64);
 DECLARE ddl LONGTEXT DEFAULT 'ALTER TABLE desired_groups ';
 DECLARE checks_cursor CURSOR FOR SELECT t.CONSTRAINT_NAME FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME AND c.TABLE_NAME=t.TABLE_NAME AND t.CONSTRAINT_NAME<>'members' WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME='desired_groups' AND t.CONSTRAINT_TYPE='CHECK' AND LOWER(c.CHECK_CLAUSE) LIKE '%members%' ORDER BY t.CONSTRAINT_NAME;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished=TRUE;
 OPEN checks_cursor;
 checks_loop: LOOP
  FETCH checks_cursor INTO constraint_name_value;
  IF finished THEN LEAVE checks_loop; END IF;
  SET ddl=CONCAT(ddl,'DROP CONSTRAINT ',CHAR(96),REPLACE(constraint_name_value,CHAR(96),CONCAT(CHAR(96),CHAR(96))),CHAR(96),',');
 END LOOP;
 CLOSE checks_cursor;
 SET @ocserv_type_ddl=CONCAT(ddl,'DROP COLUMN members,CHANGE COLUMN logical_members members LONGBLOB NOT NULL');
 PREPARE type_statement FROM @ocserv_type_ddl;
 EXECUTE type_statement;
 DEALLOCATE PREPARE type_statement;
 SET @ocserv_type_ddl=NULL;
END

